Lemma tb_law_step c need c' :
  PM.tb_law c -> 26 <= c -> c - 1 < need -> need <= c - 1 + 16384 -> need < 2 ^ 26 + 16384 ->
  c' = Z.lor (Z.max (2 * (c - 1)) need) 7 + 1 ->
