Lemma pot_text_step L s s' tg :
  2 * PM.vs_cap s <= PM.vs_cap s' ->
  credit_le (PM.credit_add (PM.cost1 L (PM.vs_cap s' + 1)) (PM.pot_text L s' (tg + 1))) (PM.pot_text L s tg).
Proof.
